         */workspace: String, 
        /**
         * The generic-password item holding the app key, in the App Group's
         * keychain access group: the account is the one for the gate the app
         * enrolled behind.
         */keychainService: String, keychainAccount: String) {
        self.root = root
        self.workspace = workspace
        self.keychainService = keychainService
        self.keychainAccount = keychainAccount
    }
}

